    98	    const [isBlockedFromChat] = useOnyx(ONYXKEYS.NVP_BLOCKED_FROM_CHAT, {
    99	        selector: (dateString) => {
   100	            if (!dateString) {
   101	                return false;
   102	            }
   103	            try {
   104	                return new Date(dateString) >= new Date();
   105	            } catch (error) {
   106	                // If the NVP is malformed, we'll assume the user is not blocked from chat. This is not expected, so if it happens we'll log an alert.
   107	                Log.alert(`[${CONST.ERROR.ENSURE_BUG_BOT}] Found malformed ${ONYXKEYS.NVP_BLOCKED_FROM_CHAT} nvp`, dateString);
