   119	
   120	    // If a user just signed in and is viewing a public report, optimistically show the composer while loading the report, since they will have write access when the response comes back.
   121	    const shouldShowComposerOptimistically = !isAnonymousUser && isPublicRoom(report) && !!reportMetadata?.isLoadingInitialReportActions;
   122	    const canPerformWriteAction = canUserPerformWriteAction(report) ?? shouldShowComposerOptimistically;
   123	    const shouldHideComposer = !canPerformWriteAction || isBlockedFromChat;
   124	    const canWriteInReport = canWriteInReportUtil(report);
   125	    const isSystemChat = isSystemChatUtil(report);
   126	    const isAdminsOnlyPostingRoom = isAdminsOnlyPostingRoomUtil(report);
   127	    const isUserPolicyAdmin = isPolicyAdmin(policy);
