   129	    const allPersonalDetails = usePersonalDetails();
   130	    const {availableLoginsList} = useShortMentionsList();
   131	    const currentUserEmail = getCurrentUserEmail();
   132	
   133	    const handleCreateTask = useCallback(
   134	        (text: string): boolean => {
   135	            const match = text.match(CONST.REGEX.TASK_TITLE_WITH_OPTIONAL_SHORT_MENTION);
   136	            if (!match) {
   137	                return false;
   138	            }
   139	            let title = match[3] ? match[3].trim().replace(/\n/g, ' ') : undefined;
   140	            if (!title) {
   141	                return false;
   142	            }
   143	
   144	            const mention = match[1] ? match[1].trim() : '';
   145	            const currentUserPrivateDomain = isEmailPublicDomain(currentUserEmail ?? '') ? '' : Str.extractEmailDomain(currentUserEmail ?? '');
   146	            const mentionWithDomain = addDomainToShortMention(mention, availableLoginsList, currentUserPrivateDomain) ?? mention;
   147	            const isValidMention = Str.isValidEmail(mentionWithDomain);
   148	
   149	            let assignee: OnyxEntry<OnyxTypes.PersonalDetails>;
   150	            let assigneeChatReport;
   151	            if (mentionWithDomain) {
   152	                if (isValidMention) {
   153	                    assignee = Object.values(allPersonalDetails ?? {}).find((value) => value?.login === mentionWithDomain) ?? undefined;
   154	                    if (!Object.keys(assignee ?? {}).length) {
   155	                        const assigneeAccountID = generateAccountID(mentionWithDomain);
   156	                        const optimisticDataForNewAssignee = setNewOptimisticAssignee(mentionWithDomain, assigneeAccountID);
   157	                        assignee = optimisticDataForNewAssignee.assignee;
   158	                        assigneeChatReport = optimisticDataForNewAssignee.assigneeReport;
   159	                    }
