   172	    const onSubmitComment = useCallback(
   173	        (text: string) => {
   174	            const isTaskCreated = handleCreateTask(text);
   175	            if (isTaskCreated) {
   176	                return;
   177	            }
   178	            addComment(report.reportID, text, true);
   179	        },
   180	        // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   181	        [report.reportID, handleCreateTask],
   182	    );
   183	
   184	    const [didHideComposerInput, setDidHideComposerInput] = useState(!shouldShowComposeInput);
   185	
   186	    useEffect(() => {
   187	        if (didHideComposerInput || shouldShowComposeInput) {
   188	            return;
   189	        }
   190	        setDidHideComposerInput(true);
   191	    }, [shouldShowComposeInput, didHideComposerInput]);
   192	
   193	    return (
   194	        <>
   195	            {!!shouldHideComposer && (
   196	                <View
   197	                    style={[
   198	                        styles.chatFooter,
   199	                        isArchivedRoom || isAnonymousUser || !canWriteInReport || (isAdminsOnlyPostingRoom && !isUserPolicyAdmin) ? styles.mt4 : {},
   200	                        shouldUseNarrowLayout ? styles.mb5 : null,
   201	                    ]}
   202	                >
   203	                    {isAnonymousUser && !isArchivedRoom && (
   204	                        <AnonymousReportFooter
   205	                            report={report}
   206	                            isSmallSizeLayout={isSmallSizeLayout}
   207	                        />
   208	                    )}
   209	                    {isArchivedRoom && <ArchivedReportFooter report={report} />}
   210	                    {!isArchivedRoom && !!isBlockedFromChat && <BlockedReportFooter />}
   211	                    {!isAnonymousUser && !canWriteInReport && isSystemChat && <SystemChatReportFooterMessage />}
   212	                    {isAdminsOnlyPostingRoom && !isUserPolicyAdmin && !isArchivedRoom && !isAnonymousUser && !isBlockedFromChat && (
   213	                        <Banner
   214	                            containerStyles={[styles.chatFooterBanner]}
   215	                            text={translate('adminOnlyCanPost')}
   216	                            icon={Expensicons.Lightbulb}
   217	                            shouldShowIcon
   218	                        />
   219	                    )}
   220	                    {!shouldUseNarrowLayout && (
   221	                        <View style={styles.offlineIndicatorContainer}>{shouldHideComposer && <OfflineIndicator containerStyles={[styles.chatItemComposeSecondaryRow]} />}</View>
   222	                    )}
   223	                </View>
   224	            )}
   225	            {!shouldHideComposer && (!!shouldShowComposeInput || !shouldUseNarrowLayout) && (
   226	                <View style={[chatFooterStyles, isComposerFullSize && styles.chatFooterFullCompose]}>
