   231	                            onComposerBlur={onComposerBlur}
   232	                            reportID={report.reportID}
   233	                            report={report}
   234	                            lastReportAction={lastReportAction}
   235	                            pendingAction={pendingAction}
   236	                            isComposerFullSize={isComposerFullSize}
   237	                            isReportReadyForDisplay={isReportReadyForDisplay}
   238	                            didHideComposerInput={didHideComposerInput}
   239	                            reportTransactions={reportTransactions}
   240	                        />
   241	                    </SwipeableView>
   242	                </View>
   243	            )}
   244	        </>
   245	    );
   246	}
