   250	export default memo(
   251	    ReportFooter,
   252	    (prevProps, nextProps) =>
   253	        deepEqual(prevProps.report, nextProps.report) &&
   254	        prevProps.pendingAction === nextProps.pendingAction &&
   255	        prevProps.isComposerFullSize === nextProps.isComposerFullSize &&
   256	        prevProps.lastReportAction === nextProps.lastReportAction &&
   257	        prevProps.isReportReadyForDisplay === nextProps.isReportReadyForDisplay &&
   258	        deepEqual(prevProps.reportMetadata, nextProps.reportMetadata) &&
   259	        deepEqual(prevProps.policy?.employeeList, nextProps.policy?.employeeList) &&
   260	        deepEqual(prevProps.policy?.role, nextProps.policy?.role) &&
   261	        deepEqual(prevProps.reportTransactions, nextProps.reportTransactions),
